const goldenNames = readdirSync(GOLDEN_DIR)
  .filter(file => file.endsWith(GOLDEN_SUFFIX))
  .map(file => file.slice(0, -GOLDEN_SUFFIX.length))
  .sort();

describe('round trip', () => {
  it.each(VARIANTS)('parse(generate(x)).report is canonicalize(x): %s', (_, input, options) => {
    const { bytes } = generate1214(input, options);
    const { report, issues } = parse1214(bytes);
    expect(report).toEqual(canonicalize(input, options));
    expect(issues.filter(issue => issue.severity === 'error')).toEqual([]);
  });

  it('parses the generated text like the generated bytes', () => {
    const { text, bytes } = generate1214(minimalInput(), OPTIONS);
    expect(parse1214(text)).toEqual(parse1214(bytes));
  });

  it('has golden files to check', () => {
    expect(goldenNames.length).toBeGreaterThan(0);
  });

  it.each(goldenNames)('%s.opcn is regenerated byte for byte from its parsed reports', name => {
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    const reports = parse1214Batch(golden).map(({ report, saveDate, softwareName }) => ({
      ...report,
      meta: { saveDate, softwareName },
    }));
    const [single] = reports;
    const { bytes } =
      reports.length === 1 && single ? generate1214(single) : generate1214Batch(reports);
    expect(Buffer.from(bytes).equals(Buffer.from(golden))).toBe(true);
  });

  it.each(goldenNames)('%s.opcn parses to the canonical form of its inputs', async name => {
    const { input, inputs, options } = (await import(
      new URL(`${name}.input.ts`, GOLDEN_DIR).href
    )) as { input?: Report1214Input; inputs?: Report1214Input[]; options: GenerateOptions };
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    const expected = (inputs ?? (input ? [input] : [])).map(each => canonicalize(each, options));
    expect(expected.length).toBeGreaterThan(0);
    expect(parse1214Batch(golden).map(result => result.report)).toEqual(expected);
    if (!inputs) {
      expect(parse1214(golden).report).toEqual(expected[0]);
    }
  });
});
